def get_local_ip():
    candidates=[]
    s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect(("192.0.2.1",9))
        candidates.append(s.getsockname()[0])
    except Exception:
        pass
    finally:
        s.close()
    try:
        candidates.append(socket.gethostbyname(socket.gethostname()))
    except Exception:
        pass
    for ip in candidates:
        if ip and not ip.startswith("127."):
            return ip
    return "127.0.0.1"

def make_qr_svg(url):
    """Create an offline QR as SVG. No Pillow/Image package is required."""
    try:
        import qrcode
        from qrcode.image.svg import SvgImage
        qr=qrcode.QRCode(version=None,error_correction=qrcode.constants.ERROR_CORRECT_M,box_size=12,border=4,image_factory=SvgImage)
        qr.add_data(url); qr.make(fit=True)
        img=qr.make_image()
        data=img.to_string()
        if isinstance(data,bytes): data=data.decode('utf-8')
        return data,None
    except Exception as e:
        return None,str(e)

