def db():
    c=sqlite3.connect(DB_FILE,timeout=10)
    c.row_factory=sqlite3.Row
    return c

def init_db():
    c=db()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS students(
      id INTEGER PRIMARY KEY,name TEXT NOT NULL,roll TEXT NOT NULL,class_name TEXT NOT NULL,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,level2_allowed INTEGER DEFAULT 0,
      level3_allowed INTEGER DEFAULT 0,appreciation_approved INTEGER DEFAULT 0,
      appreciation_presented INTEGER DEFAULT 0,appreciation_at TEXT,appreciation_presented_at TEXT,
      UNIQUE(roll,class_name));
    CREATE TABLE IF NOT EXISTS attempts(
      id INTEGER PRIMARY KEY,student_id INTEGER NOT NULL,level INTEGER NOT NULL,
      score INTEGER,total INTEGER,percentage REAL,passed INTEGER,started_at REAL,
      UNIQUE(student_id,level));
    """)
    # Safe migration for older databases.
    cols={r["name"] for r in c.execute("PRAGMA table_info(students)").fetchall()}
    for name,typ,default in [
        ("level2_allowed","INTEGER DEFAULT 0",0),("level3_allowed","INTEGER DEFAULT 0",0),
        ("appreciation_approved","INTEGER DEFAULT 0",0),("appreciation_presented","INTEGER DEFAULT 0",0),
        ("appreciation_at","TEXT",None),("appreciation_presented_at","TEXT",None),
        ("level1_admin_pass","INTEGER DEFAULT -1",-1),
        ("level2_admin_pass","INTEGER DEFAULT -1",-1),
        ("level3_admin_pass","INTEGER DEFAULT -1",-1)]:
        if name not in cols: c.execute(f"ALTER TABLE students ADD COLUMN {name} {typ}")
    c.commit(); c.close()

