def student_state(student_id):
    """Return the student's submitted/passed levels and the exact next level.

    Level 2/3 access is controlled by the admin allow flags.  Once the
    required previous level has been submitted, an explicit admin ALLOW
    is treated as the final authority.  This prevents an eligible Level 3
    student from getting stuck on the waiting page because of an old/stale
    pass flag from an earlier database version.
    """
    c=db()
    st=c.execute("SELECT * FROM students WHERE id=?",(student_id,)).fetchone()
    rows=c.execute("SELECT * FROM attempts WHERE student_id=? ORDER BY level",(student_id,)).fetchall()
    c.close()
    if not st:
        return None,rows,set(),set(),0

    submitted={int(r["level"]) for r in rows}
    passed=set()
    for r in rows:
        lvl=int(r["level"])
        try:
            override=int(st[f"level{lvl}_admin_pass"])
        except (KeyError, TypeError, ValueError):
            override=-1
        attempt_passed=int(r["passed"] or 0)==1
        if override==1 or (override==-1 and attempt_passed):
            passed.add(lvl)

    l2_allowed=int(st["level2_allowed"] or 0)==1
    l3_allowed=int(st["level3_allowed"] or 0)==1

    # Level 1 is always the first level for a new student.
    if 1 not in submitted:
        nxt=1
    # Level 2: Level 1 must be completed and admin must allow Level 2.
    elif l2_allowed and 1 in submitted and (1 in passed or int(st["level1_admin_pass"] or -1)==1) and 2 not in submitted:
        nxt=2
    # Level 3: Level 2 must be submitted and admin's Level 3 ALLOW is the
    # explicit eligibility decision. This is intentionally checked before
    # the normal score-based fallback so an eligible student cannot be stuck.
    elif l3_allowed and 2 in submitted and 3 not in submitted:
        nxt=3
    else:
        nxt=0

    return st,rows,submitted,passed,nxt


def mcq(q,a,wrong):
    opts=list(dict.fromkeys([str(a)]+[str(x) for x in wrong]))
    while len(opts)<4: opts.append(str(len(opts)+1))
    random.shuffle(opts)
    return {"q":q,"a":str(a),"o":opts}

def make_question(cls,level):
    if cls<=6:
        if level==1:
            a=random.randint(10,80); b=random.randint(2,30); op=random.choice(["+","-","×"])
            if op=="+": ans=a+b
            elif op=="-": a,b=max(a,b),min(a,b); ans=a-b
            else: a=random.randint(3,12); b=random.randint(2,10); ans=a*b
            return mcq(f"What is {a} {op} {b}?",ans,[ans+1,max(0,ans-1),ans+5])
        if level==2:
            n=random.randint(20,90); p=random.choice([10,20,25,50]); ans=n*p//100
            return mcq(f"What is {p}% of {n}?",ans,[ans+2,max(0,ans-2),n-p])
        n=random.randint(5,15); ans=n*n
        return mcq(f"What is {n}²?",ans,[n*2,ans+1,ans-2])
    if cls<=8:
        if level==1:
            a=random.randint(10,50); b=random.randint(2,20); ans=a+b
            return mcq(f"Calculate {a} + {b}.",ans,[ans+2,ans-2,ans+10])
        if level==2:
            a=random.randint(3,15); b=random.randint(2,12); ans=a*b
            return mcq(f"Calculate {a} × {b}.",ans,[ans+3,ans-3,a+b])
        c=random.randint(2,15); x=random.randint(3,15)
        return mcq(f"If x + {c} = {x+c}, what is x?",x,[x+1,x-1,c])
    if cls<=10:
        if level==1:
            a=random.randint(2,15); b=random.randint(2,15); ans=a*a+b*b
            return mcq(f"Find {a}² + {b}².",ans,[ans+1,ans-1,a+b])
        if level==2:
            a=random.randint(2,12); b=random.randint(2,12); c=random.randint(1,20); ans=a*b+c
            return mcq(f"Evaluate ({a} × {b}) + {c}.",ans,[ans+2,ans-2,a+b+c])
        a=random.randint(2,9); b=random.randint(2,9)
        return mcq(f"For x² − {a+b}x + {a*b} = 0, the smaller root is:",min(a,b),[max(a,b),a+b,a*b])
    if level==1:
        a=random.randint(2,12); b=random.randint(2,12); ans=a*a+b*b-a*b
        return mcq(f"Evaluate {a}² + {b}² − {a}×{b}.",ans,[ans+1,ans-1,a+b])
    if level==2:
        n=random.randint(2,9); return mcq(f"If f(x)=x², what is f({n})?",n*n,[n,2*n,n*n+1])
    # Hard level for Classes 11–12: generate a large variety of questions.
    # The old version only varied `a` from 2–9, producing just 8 unique
    # question texts while Level 3 requires 25 questions. That caused the
    # question generator to loop forever, so the Level 3 quiz page never
    # appeared for those students.
    kind=random.choice([1,2,3,4])
    if kind==1:
        a=random.randint(2,15); b=random.randint(1,12)
        return mcq(f"The derivative of x² + {a}x + {b} is:",f"2x + {a}",[f"x + {a}",f"2x + {b}",f"x² + {a}"])
    if kind==2:
        a=random.randint(2,12); b=random.randint(1,15)
        return mcq(f"The derivative of {a}x² + {b}x + 7 is:",f"{2*a}x + {b}",[f"{a}x + {b}",f"{2*a}x + 7",f"{a}x² + {b}"])
    if kind==3:
        a=random.randint(2,10); b=random.randint(1,9)
        ans=2*a+b
        return mcq(f"If f(x)={a}x² + {b}x + 4, what is f'(1)?",ans,[a+b,2*a+4,a*b])
    a=random.randint(2,12); b=random.randint(1,12)
    ans=a*a+b*b
    return mcq(f"Evaluate {a}² + {b}².",ans,[ans+2,ans-2,a*b])

def questions(cls,level):
    out=[]; seen=set(); attempts=0
    target=LEVELS[level]["questions"]
    while len(out)<target:
        x=make_question(cls,level)
        attempts += 1
        if x["q"] not in seen:
            seen.add(x["q"]); out.append(x)
        # Safety fallback: never hang the quiz if a future question bank
        # accidentally has fewer unique questions than the requested count.
        if attempts > target*100:
            out.append(x)
            attempts=0
    return out[:target]

def roll_class_ok(roll,cls):
    if not roll.isdigit() or len(roll)<3: return False,None
    first2=int(roll[:2])
    inferred=first2 if first2 in (10,11,12) else int(roll[0])
    return inferred==cls,inferred

def registration(msg=""):
    err=f'<div class="card danger">{html.escape(msg)}</div>' if msg else ""
    opts="".join(f'<option value="{x}">Class {x}</option>' for x in CLASSES)
    return page("Mathematics Quiz",f"""<div class="card" style="text-align:center;padding:34px 22px">
<img class="logo" src="data:image/png;base64,{LOGO_B64}"><div style="font-size:13px;font-weight:950;letter-spacing:2px;color:#a87810;margin-top:12px">TAIYEBI HIGHER SECONDARY SCHOOL UJJAIN</div><h1 style="font-size:clamp(34px,7vw,54px);margin-top:10px">MATHEMATICS QUIZ</h1>
<p class="muted" style="font-size:16px">2026 • Classes 5–12</p></div>{err}
<div class="card"><h2>Student Registration</h2><p class="muted">Enter your details below to enter the Mathematics Quiz.</p><form method="post" action="/register" autocomplete="off">
<label>Student Name</label><input name="name" required>
<label>Roll Number</label><input name="roll" inputmode="numeric" required>
<label>Class</label><select name="class_name" required>{opts}</select>
<button type="submit">START QUIZ →</button></form></div>""")

def parse_cookie(handler):
    raw=handler.headers.get("Cookie","")
    for x in raw.split(";"):
        if x.strip().startswith("sid="): return x.strip()[4:]
    return ""

def save_attempt(s):
    if s.get("finished"): return
    level=s["level"]; qs=s["questions"]; answers=s["answers"]
    score=sum(str(answers.get(i,""))==str(q["a"]) for i,q in enumerate(qs))
    total=len(qs); pct=round(score*100/total,1); passed=int(pct>=LEVELS[level]["pass"])
    c=db()
    c.execute("""INSERT OR REPLACE INTO attempts(student_id,level,score,total,percentage,passed,started_at)
                 VALUES(?,?,?,?,?,?,?)""",(s["student_id"],level,score,total,pct,passed,s["started"]))
    c.commit(); c.close()
    s["finished"]=True
    s["score"]=score; s["pct"]=pct; s["passed"]=passed

def choose_level(student_id,requested=1):
    st,rows,submitted,passed,nxt=student_state(student_id)
    if not st:
        return 0
    # Ignore stale URL level values. Open only the first currently available level.
    return nxt

class StudentHandler(BaseHTTPRequestHandler):
    def log_message(self,*args): pass
    def sendhtml(self,x,status=200,extra=None):
        b=x.encode()
        self.send_response(status); self.send_header("Content-Type","text/html;charset=utf-8"); self.send_header("Content-Length",str(len(b)))
        if extra:
            for k,v in extra: self.send_header(k,v)
        self.end_headers(); self.wfile.write(b)
    def redirect(self,path,cookie=None):
        self.send_response(302); self.send_header("Location",path)
        if cookie:self.send_header("Set-Cookie",cookie)
        self.send_header("Cache-Control","no-store"); self.end_headers()
    def _do_GET(self):
        path=urlparse(self.path).path; q=parse_qs(urlparse(self.path).query); token=parse_cookie(self)
        if path == "/qr":
            self.sendhtml(qr_page(f"http://{get_local_ip()}:{getattr(self, 'server_port', PORT)}/register"))
            return
        s=SESSIONS.get(token)
        if path in ("/", "/register"):
            self.sendhtml(registration()); return
        if path=="/waiting":
            if not s:
                self.redirect("/"); return
            st,rows,submitted,passed,nxt=student_state(s["student_id"])
            if nxt in (1,2,3):
                self.redirect(f"/start?level={nxt}"); return
            levels_done=", ".join("Level "+str(x) for x in sorted(submitted)) or "None"
            last=max(submitted) if submitted else 0
            next_name="Level 2" if last==1 else ("Level 3" if last==2 else "completed")
            body=(f'<div class="card" style="text-align:center"><img class="logo" src="data:image/png;base64,{LOGO_B64}">'
                  f'<div style="font-size:11px;font-weight:900;letter-spacing:2px;color:#a87810">ASSESSMENT STATUS</div>'
                  f'<h1>LEVEL COMPLETED</h1><p class="muted">Your submission was saved successfully. The next level will appear after administrator approval.</p>'
                  f'<div style="display:inline-block;margin:12px 0;padding:10px 16px;border-radius:999px;background:#fff7df;border:1px solid #e7c45c">Completed: {html.escape(levels_done)}</div>'
                  f'<p><b>Next:</b> {html.escape(next_name)}</p><br>'
                  f'<a class="btn" href="/">GO TO HOME PAGE</a></div>')
            self.sendhtml(page("Waiting",body)); return
        if path=="/start":
            if not s: self.redirect("/"); return
            requested=int(q.get("level",[1])[0]) if q.get("level",[1])[0].isdigit() else 1
            level=choose_level(s["student_id"],requested)
            if level==0:
                self.redirect("/waiting")
                return
            try: qs=questions(s["class"],level)
            except Exception as e: self.sendhtml(registration("Question error: "+str(e))); return
            s.update(level=level,questions=qs,answers={},started=time.time(),finished=False,score=None,pct=None,passed=None)
            self.redirect("/quiz?q=0"); return
        if path=="/quiz":
            if not s or "questions" not in s or s.get("finished"): self.redirect("/"); return
            i=max(0,min(len(s["questions"])-1,int(q.get("q",[0])[0])))
            x=s["questions"][i]; selected=s["answers"].get(i,"")
            opts="".join(f'<label class="opt"><input type="radio" name="answer" value="{html.escape(str(o))}" {"checked" if str(o)==str(selected) else ""} onchange="toggle()"> {html.escape(str(o))}</label>' for o in x["o"])
            prev=f'<button type="button" onclick="go({i-1})">← PREVIOUS</button>' if i else '<span></span>'
            nxt=f'<button type="button" id="next" onclick="go({i+1})" disabled>NEXT →</button>' if i<len(s["questions"])-1 else '<button type="button" id="next" onclick="finish()" disabled>SUBMIT QUIZ ✓</button>'
            left=max(0,int(LEVELS[s["level"]]["minutes"]*60-(time.time()-s["started"])))
            body=f"""<div class="card"><div class="top"><div><b style="color:#f5d66b">LEVEL {s["level"]} • {LEVELS[s["level"]]["name"]}</b><div class="muted">{html.escape(s["name"])} • Class {s["class"]} • Roll {html.escape(s["roll"])}</div></div><div id="timer" class="timer">--:--</div></div>
<div class="bar"><i style="width:{(i+1)*100//len(s["questions"])}%"></i></div><small>QUESTION {i+1} OF {len(s["questions"])}</small><div class="question">{html.escape(x["q"])}</div><div>{opts}</div><div class="nav">{prev}{nxt}</div></div>
<script>
let left={left}, navigating=false, sent=false;
function tick(){{let t=document.getElementById('timer');t.textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');if(left<=0){{finish(true);return}}left--;setTimeout(tick,1000)}}tick();
function toggle(){{let a=document.querySelector('input[name=answer]:checked');document.getElementById('next').disabled=!a}}
function current(){{let a=document.querySelector('input[name=answer]:checked');return a?a.value:''}}
function go(n){{if(!current())return;navigating=true;fetch('/answer',{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},body:new URLSearchParams({{q:'{i}',answer:current()}})}}).then(()=>location='/quiz?q='+n)}}
function finish(auto){{if(sent)return;sent=true;navigating=true;let f=document.createElement('form');f.method='POST';f.action='/submit';let q=document.createElement('input');q.name='q';q.value='{i}';let a=document.createElement('input');a.name='answer';a.value=current();let z=document.createElement('input');z.name='finish';z.value='1';f.append(q,a,z);document.body.appendChild(f);f.submit()}}
document.addEventListener('visibilitychange',()=>{{if(document.visibilityState==='hidden'&&!navigating)finish(true)}});history.pushState(null,'',location.href);window.onpopstate=()=>finish(true);toggle();
</script>"""
            self.sendhtml(page("Quiz",body)); return
        if path=="/processing":
            if not s: self.redirect("/"); return
            c=db(); st=c.execute("SELECT * FROM students WHERE id=?",(s["student_id"],)).fetchone()
            rows=c.execute("SELECT * FROM attempts WHERE student_id=? AND level IN(1,2,3) ORDER BY level",(s["student_id"],)).fetchall(); c.close()
            if not st["appreciation_presented"]: self.redirect("/"); return
            cards="".join(f'<div class="pill">LEVEL {r["level"]}: {r["score"]}/{r["total"]} • {r["percentage"]}% ✓</div><br>' for r in rows)
            total_score=sum(r["score"] for r in rows); total_q=sum(r["total"] for r in rows); overall=round(total_score*100/total_q,1) if total_q else 0
            body=f'<div class="appreciation"><img class="logo" src="data:image/png;base64,{LOGO_B64}"><h1>🏆 APPRECIATION</h1><h2>Congratulations, {html.escape(st["name"])}!</h2><p>Roll {html.escape(st["roll"])} • Class {st["class_name"]}</p>{cards}<h2>Overall: {total_score}/{total_q} • {overall}%</h2><p class="ok">All three levels completed successfully.</p><div style="margin-top:28px"><a class="btn" href="/">EXIT TO SITE</a></div></div>'
            self.sendhtml(page("Appreciation",body)); return
        self.sendhtml(page("404",'<div class="card"><h1>404</h1><a class="btn" href="/">HOME</a></div>'),404)
    def do_GET(self):
        try:
            self._do_GET()
        except Exception as e:
            print("GET ERROR:", repr(e))
            try:
                self.sendhtml(page("Server Error", f'<div class="card" style="text-align:center"><h1>Something went wrong</h1><p class="muted">The quiz server hit an internal error.</p><a class="btn" href="/">RETURN TO QUIZ</a></div>'), 500)
            except Exception:
                pass
    def _do_POST(self):
        length=int(self.headers.get("Content-Length",0)); data=parse_qs(self.rfile.read(length).decode()); path=urlparse(self.path).path; token=parse_cookie(self); s=SESSIONS.get(token)
        if path=="/register":
            name=data.get("name",[""])[0].strip(); roll=data.get("roll",[""])[0].strip(); cls=data.get("class_name",[""])[0].strip()
            if not name or cls not in [str(x) for x in CLASSES] or not roll.isdigit():
                self.sendhtml(registration("Please enter valid registration details.")); return
            ok,inferred=roll_class_ok(roll,int(cls))
            if not ok:
                self.sendhtml(registration(f"Class mismatch: roll {html.escape(roll)} belongs to Class {inferred}.")); return
            c=db(); row=c.execute("SELECT id,appreciation_presented FROM students WHERE roll=? AND class_name=?",(roll,cls)).fetchone()
            if row: sid=row["id"]; c.execute("UPDATE students SET name=? WHERE id=?",(name,sid))
            else: sid=c.execute("INSERT INTO students(name,roll,class_name) VALUES(?,?,?)",(name,roll,cls)).lastrowid
            c.commit(); c.close()
            token=str(random.getrandbits(128)); SESSIONS[token]={"student_id":sid,"name":name,"roll":roll,"class":int(cls)}
            # Always calculate the student's NEXT AVAILABLE level immediately after registration.
            st,rows,submitted,passed,nxt=student_state(sid)
            if 3 in passed and st["appreciation_presented"]:
                dest="/processing"
            elif nxt in (1,2,3):
                dest=f"/start?level={nxt}"
            else:
                dest="/waiting"
            self.redirect(dest,f"sid={token}; Path=/; HttpOnly; SameSite=Lax"); return
        if not s: self.sendhtml(registration("Session expired. Please register again.")); return
        if path=="/answer":
            try:i=int(data.get("q",["0"])[0])
            except:i=0
            if 0<=i<len(s.get("questions",[])): s["answers"][i]=data.get("answer",[""])[0]
            self.send_response(204); self.end_headers(); return
        if path=="/submit":
            if s.get("finished"): self.redirect("/waiting"); return
            try:i=int(data.get("q",["0"])[0])
            except:i=0
            if 0<=i<len(s["questions"]): s["answers"][i]=data.get("answer",[""])[0]
            save_attempt(s)
            # Never expose the score to the student.
            self.redirect("/waiting"); return
        self.sendhtml(page("404",'<div class="card"><h1>404</h1></div>'),404)

    def do_POST(self):
        try:
            self._do_POST()
        except Exception as e:
            print("POST ERROR:", repr(e))
            try:
                self.sendhtml(page("Server Error", f'<div class="card" style="text-align:center"><h1>Something went wrong</h1><p class="muted">Please return to the quiz and try again.</p><a class="btn" href="/">RETURN TO QUIZ</a></div>'), 500)
            except Exception:
                pass

def serve(cls,port):
    srv=ThreadingHTTPServer((HOST,port),cls)
    print(f"{cls.__name__}: http://{HOST}:{port}", flush=True)
    srv.serve_forever()

def find_free_port(preferred):
    # If an older broken copy is still using 8080, automatically use a free port
    # instead of silently exiting and leaving the browser connected to the old copy.
    for p in [preferred,8090,8091,8092,8093,8094,8095]:
        try:
            test=ThreadingHTTPServer((HOST,p),StudentHandler)
            test.server_close()
            return p
        except OSError:
            continue
    raise OSError("No free local port was found. Close old quiz Python windows and try again.")

def main():
    try:
        init_db()
    except Exception as e:
        print("DATABASE STARTUP ERROR:",repr(e),flush=True)
        print("The database file may be locked by another copy of the quiz.",flush=True)
        input("Press Enter to close...")
        return
    try:
        actual_port=find_free_port(PORT)
        ip=get_local_ip()
        url=f"http://{ip}:{actual_port}/"
        print("============================================",flush=True)
        print(" TAIYEBI MATHEMATICS QUIZ - PHONE HOST",flush=True)
        print(f" STUDENT URL: {url}",flush=True)
        print(f" QR PAGE:     http://{ip}:{actual_port}/qr",flush=True)
        if actual_port != PORT:
            print(f" WARNING: port {PORT} is already occupied.",flush=True)
            print(" This copy is using the free port above.",flush=True)
        print("============================================",flush=True)
        threading.Timer(0.8, lambda: webbrowser.open(f"http://127.0.0.1:{actual_port}/qr")).start()
        serve(StudentHandler, actual_port)
    except KeyboardInterrupt:
        print("Student Quiz stopped.",flush=True)
    except Exception as e:
        print("SERVER STARTUP ERROR:",repr(e),flush=True)
        input("Press Enter to close...")

if __name__=="__main__":
    main()
